cd /tmp/colorspec && python3 -c "
import json, glob, string
res={}
for f in glob.glob('chunks/out*.json'):
    res.update(json.load(open(f)))
print('total', len(res))
print('unmapped', len([k for k,v in res.items() if v[0] is None]))
recognized={k:v[0] for k,v in res.items() if v[0] not in (None,'white')}
print('recognized count', len(recognized))
hexd=set('0123456789ABCDEFabcdef')
named={k:v for k,v in recognized.items() if not all(ch in hexd for ch in k[1:])}
print('NON-HEX recognized:', sorted(named.items()))
bad=[]
for k,v in recognized.items():
    if all(ch in hexd for ch in k[1:]):
        exp='#'+''.join(ch.lower()*2 for ch in k[1:])
        if v!=exp: bad.append((k,v,exp))
print('hex mismatches:', bad[:20], len(bad))
allhex=['c'+a+b+c for a in hexd for b in hexd for c in hexd]
notrec=[k for k in allhex if k not in recognized]
print('hex NOT recognized:', len(notrec), notrec[:30])
json.dump(res, open('sweep62.json','w'))
"

